					{"ZOffset", 0},
					{"Orientation", Enum.ParticleOrientation.VelocityParallel},
					{"VelocityInheritance", 0},
					{"TimeScale", 0.6},
					{"Squash", NumberSequence.new({NumberSequenceKeypoint.new(0,-1.82,0),NumberSequenceKeypoint.new(0.398506,0.7125,0),NumberSequenceKeypoint.new(1,3,0)})},
					{"Shape", Enum.ParticleEmitterShape.Box},
					{"ShapeInOut", Enum.ParticleEmitterShapeInOut.Outward},
					{"ShapeStyle", Enum.ParticleEmitterShapeStyle.Volume},
					{"ShapePartial", 1},
					{"FlipbookLayout", Enum.ParticleFlipbookLayout.None},
					{"FlipbookMode", Enum.ParticleFlipbookMode.Loop},
					{"FlipbookFramerate", NumberRange.new(1.09863,1.09863)},
					{"FlipbookStartRandom", false},
					{"Brightness", 25},
				} },
			{ t = 0.49667, kind = "sfx", name = "WolfFangFlashBackflip2", dur = 2.00698, pos = true,
				props = {
					{"SoundId", "rbxassetid://89414209148623"},
					{"Volume", 3},
					{"PlaybackSpeed", 1},
					{"Looped", false},
					{"TimePosition", 0},
					{"RollOffMode", Enum.RollOffMode.InverseTapered},
					{"RollOffMinDistance", 10},
					{"RollOffMaxDistance", 10000},
				} },
		}
		local Debris = game:GetService("Debris")
		local SoundService = game:GetService("SoundService")
		local RunService = game:GetService("RunService")

		local function mountFor(m)
			local att = Instance.new("Attachment")
			local part = m and m.part and fxChar:FindFirstChild(m.part, true)
			if part and part:IsA("BasePart") then
				att.CFrame = m.cf or CFrame.new()
				att.Parent = part
				return att, att
			end
			local p = Instance.new("Part")
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.Transparency = 1
			p.Size = Vector3.new(0.2, 0.2, 0.2)
			p.CFrame = fxRoot.CFrame * ((m and m.cf) or CFrame.new())
			p:SetAttribute("_Replay", true)
			p.Parent = workspace
			att.Parent = p
			return att, p
		end

		local function setProps(inst, props)
			for _, kv in ipairs(props) do
				pcall(function() inst[kv[1]] = kv[2] end)
			end
		end

		local function mkPart(d)
			local ok, o = pcall(Instance.new, d.cls)
			local p = (ok and o and o:IsA("BasePart")) and o or Instance.new("Part")
			for _, kv in ipairs(d.props) do
				pcall(function() p[kv[1]] = kv[2] end)
			end
			p.Name = d.name
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.Massless = true
			for _, k in ipairs(d.kids or {}) do
				local okK, o2 = pcall(Instance.new, k.cls)
				if okK and o2 then
					for _, kv in ipairs(k.props) do
						pcall(function() o2[kv[1]] = kv[2] end)
					end
					o2.Parent = p
				end
			end
			return p
		end

		-- a spawned object (sword, dummy, parts...) rebuilt from its parts
		local function playObj(e)
			local holder = Instance.new("Model")
			holder:SetAttribute("_Replay", true)
			holder.Name = e.name or "Spawned"
			local made = {}
			for i, d in ipairs(e.spec.parts) do
				local ok, p = pcall(mkPart, d)
				if ok and p then
					made[i] = p
					p.Parent = holder
				end
			end
			if next(made) == nil then
				holder:Destroy()
				return
			end
			local attached = e.mount and e.mount.part and fxChar:FindFirstChild(e.mount.part, true)
			local pivotCF
			if attached and attached:IsA("BasePart") then
				pivotCF = attached.CFrame * e.mount.cf
			else
				attached = nil
				pivotCF = fxRoot.CFrame * (e.rel or CFrame.new())
			end
			for i, d in ipairs(e.spec.parts) do
				if made[i] then made[i].CFrame = pivotCF * d.rel end
			end
			holder.Parent = workspace
			local life = (e.dur or 2.5)
			if attached then -- held / worn: follows the animation
				for _, p in pairs(made) do
					p.Anchored = false
					local w = Instance.new("WeldConstraint")
					w.Part0 = attached
					w.Part1 = p
					w.Parent = p
				end
			elseif e.path and #e.path >= 2 then -- flies / moves on its own
				local root0 = fxRoot.CFrame
				task.spawn(function()
					local t0 = os.clock()
					local path = e.path
					local i = 1
					while holder.Parent and os.clock() - t0 < life do
						local t = os.clock() - t0
						while i < #path - 1 and path[i + 1][1] < t do i += 1 end
						local a, b = path[i], path[i + 1]
						local al = math.clamp((t - a[1]) / math.max(b[1] - a[1], 1e-4), 0, 1)
						local pc = root0 * a[2]:Lerp(b[2], al)
						for k, d in ipairs(e.spec.parts) do
							if made[k] then made[k].CFrame = pc * d.rel end
						end
						RunService.Heartbeat:Wait()
					end
				end)
			end
			Debris:AddItem(holder, life + 0.3)
		end

		-- cutscene camera: plays the recorded camera path (relative to where you stand), then gives the camera back
		local function playCam(e)
			local cam = workspace.CurrentCamera
			local pts = e.cam
			if not cam or not pts or #pts < 2 then return end
			local rootCF = fxRoot.CFrame
			local oldType, oldFov = cam.CameraType, cam.FieldOfView
			cam.CameraType = Enum.CameraType.Scriptable
			pcall(function() workspace:SetAttribute("_ReplayCam", true) end)
			local t0 = os.clock()
			local last = pts[#pts][1]
			local i = 1
			while os.clock() - t0 < last do
				local t = os.clock() - t0
				while i < #pts - 1 and pts[i + 1][1] < t do i += 1 end
				local a, b = pts[i], pts[i + 1]
				local al = math.clamp((t - a[1]) / math.max(b[1] - a[1], 1e-4), 0, 1)
				cam.CFrame = rootCF * a[2]:Lerp(b[2], al)
				cam.FieldOfView = a[3] + (b[3] - a[3]) * al
				RunService.RenderStepped:Wait()
			end
			cam.CameraType = oldType
			cam.FieldOfView = oldFov
			pcall(function() workspace:SetAttribute("_ReplayCam", nil) end)
		end

		local TweenService = game:GetService("TweenService")
		local function playGui(e)
			local g = e.gui
			if not g or not g.nodes or #g.nodes == 0 then return end
			local insts = {}
			for i, n in ipairs(g.nodes) do
				local inst = Instance.new(n.c)
				inst.Name = n.n
				for _, kv in ipairs(n.pr) do pcall(function() inst[kv[1]] = kv[2] end) end
				insts[i] = inst
			end
			for i, n in ipairs(g.nodes) do
				if n.p > 0 and insts[n.p] then insts[i].Parent = insts[n.p] end
			end
			local root = insts[1]
			root:SetAttribute("_Replay", true)
			local okH, hui = pcall(function() return gethui() end)
			root.Parent = (okH and hui) or lp:WaitForChild("PlayerGui")
			task.spawn(function()
				local t0 = os.clock()
				for _, k in ipairs(g.keys or {}) do
					local w = k[1] - (os.clock() - t0)
					if w > 0 then task.wait(w) end
					local inst = insts[k[2]]
					if inst then
						pcall(function()
							local tv = typeof(k[4])
							if tv == "UDim2" or tv == "number" or tv == "Color3" or tv == "Vector2" or tv == "UDim" then
								TweenService:Create(inst, TweenInfo.new(0.06, Enum.EasingStyle.Linear), { [k[3]] = k[4] }):Play()
							else
								inst[k[3]] = k[4]
							end
						end)
					end
				end
			end)
			task.delay((e.dur or g.dur or 3) + 0.5, function() pcall(function() root:Destroy() end) end)
		end

		local function playFX(e)
			if e.kind == "gui" then return playGui(e) end
			if e.kind == "obj" then return playObj(e) end
			if e.kind == "cam" then return playCam(e) end
			if e.kind == "sfx" then
				local s = Instance.new("Sound")
				s:SetAttribute("_Replay", true)
				setProps(s, e.props)
				s.Parent = e.pos and fxRoot or SoundService
				s:Play()
				Debris:AddItem(s, e.dur or 5)
				return
			end

			local cls = e.class
			local fx = Instance.new(cls)
			fx:SetAttribute("_Replay", true)
			fx.Name = e.name or cls
			setProps(fx, e.props)
			local life = (e.dur or 2) + 2

			if cls == "Highlight" then
				fx.Adornee = fxChar
				fx.Parent = fxChar
			elseif cls == "Explosion" then
				fx.BlastPressure = 0
				fx.DestroyJointRadiusPercent = 0
				fx.Position = (fxRoot.CFrame * ((e.mount and e.mount.cf) or CFrame.new())).Position
				fx.Parent = workspace
			elseif cls == "ForceField" then
				fx.Parent = fxChar
			elseif cls == "Atmosphere" or fx:IsA("PostEffect") then
				fx.Parent = game:GetService("Lighting")
			elseif cls == "Beam" or cls == "Trail" then
				local a0, h0 = mountFor(e.att0 or e.mount)
				local a1, h1 = mountFor(e.att1 or e.mount)
				fx.Attachment0, fx.Attachment1 = a0, a1
				fx.Parent = a0
				Debris:AddItem(h0, life)
				Debris:AddItem(h1, life)
			else
				local att, holder = mountFor(e.mount)
				if cls == "Fire" or cls == "Smoke" or cls == "Sparkles" then
					fx.Parent = att.Parent -- these legacy effects need a BasePart
				else
					fx.Parent = att
				end
				if cls == "ParticleEmitter" then
					if e.enabled then
						fx.Enabled = true
						task.delay(e.dur or 1.5, function() pcall(function() fx.Enabled = false end) end)
					else
						fx.Enabled = false
						fx:Emit(e.emit or 10)
					end
				end
				Debris:AddItem(holder, life)
			end
			Debris:AddItem(fx, life)
		end

		for _, e in ipairs(FX) do
			task.delay(e.t or 0, function()
				local ok, err = pcall(playFX, e)
				if not ok then warn("[FX] skipped:", err) end
			end)
		end

	end)
	if not ok then warn("[FX] failed (animation unaffected):", err) end
end

if _G.StopNpcAnim then pcall(_G.StopNpcAnim) end

local function notify(text)
	print("[NpcAnim] " .. text)
	pcall(function()
		game:GetService("StarterGui"):SetCore("SendNotification", {
			Title = "NPC anim", Text = text, Duration = 3,
		})
	end)
end

local playing, watched, ctrlConns = {}, {}, {}
local shutdown = false

local function isNpc(m)
	if not (m and m:IsA("Model")) or m == lp.Character then return false end
	if Players:GetPlayerFromCharacter(m) then return TARGET_PLAYERS end
	return true
end

local function rigOk(h)
	return RIG == "Custom" or h.RigType.Name == RIG
end

local function myPos()
	local r = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
	return r and r.Position
end

local function inRange(m)
	local hrp = m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
	local me = myPos()
	if not (hrp and me) then return false end
	return (hrp.Position - me).Magnitude <= TARGET_RANGE
end

local function nameOk(m)
	return TARGET_NAME == "" or m.Name == TARGET_NAME
end

-- plays the captured frames (and movement) on one NPC
local function playOn(npc)
	if shutdown or playing[npc] then return end
	local hum = npc:FindFirstChildOfClass("Humanoid")
	if not hum or hum.Health <= 0 or not rigOk(hum) then return end

	local motors, count = {}, 0
	for _, d in ipairs(npc:GetDescendants()) do
		if d:IsA("Motor6D") and JOINTS[d.Name] and d.Part1 and not motors[d.Name] then
			motors[d.Name] = d
			count += 1
		end
	end
	if count == 0 then return end

	local function apply(pose)
		for name, cf in pairs(pose) do
			local m = motors[name]
			if m then m.Transform = cf end
		end
	end

	local animate = npc:FindFirstChild("Animate")
	local animateWasDisabled = animate and animate.Disabled
	local detached = {}
	local function detachAnimators()
		for _, d in ipairs(hum:GetChildren()) do
			if d:IsA("Animator") then
				detached[#detached + 1] = d
				d.Parent = nil
			end
		end
	end
	if DISABLE_DEFAULT_ANIMATE then
		if animate then pcall(function() animate.Disabled = true end) end
		detachAnimators()
	end

	local accumulated, index, elapsed = 0, 1, 0
	local lastFrame
	local conns = {}
	local stopped = false

	local rootPart = npc:FindFirstChild("HumanoidRootPart") or npc.PrimaryPart
	local rootOrigin = rootPart and rootPart.CFrame
	local rootIdx = 0
	local useRoot = MOVE_ROOT and ROOT ~= nil and rootPart ~= nil

	local function rootOffset(t)
		while ROOT[rootIdx + 1] and ROOT[rootIdx + 1].t <= t do rootIdx += 1 end
		local prev, nxt = ROOT[rootIdx], ROOT[rootIdx + 1]
		local pt, pcf = 0, CFrame.new()
		if prev then pt, pcf = prev.t, prev.cf end
		local o = pcf
		if nxt then o = pcf:Lerp(nxt.cf, math.clamp((t - pt) / math.max(nxt.t - pt, 1e-6), 0, 1)) end
		if MOVE_SCALE ~= 1 then o = CFrame.new(o.Position * MOVE_SCALE) * (o - o.Position) end
		return o
	end

	local function stop()
		if stopped then return end
		stopped = true
		playing[npc] = nil
		for _, c in ipairs(conns) do c:Disconnect() end
		table.clear(conns)
		for _, m in pairs(motors) do m.Transform = CFrame.new() end
		if useRoot and rootPart.Parent then rootPart.AssemblyLinearVelocity = Vector3.zero end
		if #detached > 0 then
			for _, a in ipairs(hum:GetChildren()) do
				if a:IsA("Animator") then a:Destroy() end
			end
			for _, a in ipairs(detached) do a.Parent = hum end
		end
		if animate and DISABLE_DEFAULT_ANIMATE then pcall(function() animate.Disabled = animateWasDisabled end) end
	end
	playing[npc] = stop
	if runFX and rootPart then task.spawn(runFX, npc, rootPart) end

	table.insert(conns, hum.Died:Connect(stop))
	table.insert(conns, npc.AncestryChanged:Connect(function()
		if not npc:IsDescendantOf(game) then stop() end
	end))
	table.insert(conns, RunService.Heartbeat:Connect(function(dt)
		if stopped then return end
		accumulated += dt * SPEED
		elapsed += dt * SPEED
		if DISABLE_DEFAULT_ANIMATE then detachAnimators() end
		if useRoot and rootPart.Parent then
			rootPart.CFrame = rootOrigin * rootOffset(math.min(elapsed, ROOT_END))
			rootPart.AssemblyLinearVelocity = Vector3.zero
			rootPart.AssemblyAngularVelocity = Vector3.zero
		end
		local rootDone = not useRoot or elapsed >= ROOT_END

		while frames[index] and accumulated >= frames[index].dt do
			accumulated -= frames[index].dt
			lastFrame = frames[index]
			index += 1
		end

		local nextFrame = frames[index]
		if not nextFrame then
			if lastFrame then apply(lastFrame.j) end
			if not rootDone then return end
			if LOOP_FOREVER then
				index, accumulated, elapsed, rootIdx = 1, 0, 0, 0
				if useRoot then rootOrigin = rootPart.CFrame end
				if runFX and rootPart then task.spawn(runFX, npc, rootPart) end
			else
				stop()
			end
			return
		end

		if lastFrame and SMOOTH then
			local alpha = math.clamp(accumulated / math.max(nextFrame.dt, 1e-6), 0, 1)
			for name, cf in pairs(nextFrame.j) do
				local m = motors[name]
				local from = lastFrame.j[name]
				if m and from then m.Transform = from:Lerp(cf, alpha) end
			end
		elseif lastFrame then
			apply(lastFrame.j)
		end
	end))
end

local function nearestNpc()
	local best, bestDist
	local me = myPos()
	for _, d in ipairs(workspace:GetDescendants()) do
		if d:IsA("Humanoid") and d.Health > 0 and isNpc(d.Parent) and rigOk(d) and nameOk(d.Parent) then
			local hrp = d.Parent:FindFirstChild("HumanoidRootPart") or d.Parent.PrimaryPart
			if hrp then
				local dist = me and (hrp.Position - me).Magnitude or 0
				if dist <= TARGET_RANGE and (not bestDist or dist < bestDist) then
					best, bestDist = d.Parent, dist
				end
			end
		end
	end
	return best
end

-- AUTO: every NPC or player you hit (health drops while you are near) plays the animation
local function watch(hum)
	local m = hum.Parent
	if watched[hum] or not isNpc(m) or not nameOk(m) or not rigOk(hum) then return end
	watched[hum] = true
	local last = hum.Health
	table.insert(ctrlConns, hum.HealthChanged:Connect(function(h)
		local dropped = h < last
		last = h
		if dropped and h > 0 and inRange(m) then playOn(m) end
	end))
end

local function stopAll()
	shutdown = true
	for _, c in ipairs(ctrlConns) do c:Disconnect() end
	table.clear(ctrlConns)
	local list = {}
	for _, fn in pairs(playing) do list[#list + 1] = fn end
	for _, fn in ipairs(list) do pcall(fn) end
	_G.StopNpcAnim = nil
end
_G.StopNpcAnim = stopAll

if AUTO then
	for _, d in ipairs(workspace:GetDescendants()) do
		if d:IsA("Humanoid") then watch(d) end
	end
	table.insert(ctrlConns, workspace.DescendantAdded:Connect(function(d)
		if d:IsA("Humanoid") then
			task.defer(function() if d.Parent then watch(d) end end)
		end
	end))
	notify("Auto mode on: hit an NPC or player and it plays the animation (" .. string.format("%.2fs", LENGTH) .. ")")
end

if PLAY_ON_START or not AUTO then
	local npc = TARGET_MODEL or nearestNpc()
	if npc then
		playOn(npc)
		if not AUTO then notify("Playing on " .. npc.Name) end
	else
		notify("No matching NPC near you (" .. RIG .. "). " .. (AUTO and "Waiting for a hit." or "Stand closer or raise TARGET_RANGE."))
		if not AUTO then shutdown = true end
	end
end
