					{"Color", ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.new(1,1,1)),ColorSequenceKeypoint.new(1,Color3.new(1,1,1))})},
					{"Transparency", NumberSequence.new({NumberSequenceKeypoint.new(0,0,0),NumberSequenceKeypoint.new(0.1,0.160648,0),NumberSequenceKeypoint.new(0.2,0.312266,0),NumberSequenceKeypoint.new(0.3,0.453823,0),NumberSequenceKeypoint.new(0.4,0.584051,0),NumberSequenceKeypoint.new(0.5,0.701365,0),NumberSequenceKeypoint.new(0.6,0.803739,0),NumberSequenceKeypoint.new(0.7,0.888522,0),NumberSequenceKeypoint.new(0.8,0.952182,0),NumberSequenceKeypoint.new(0.9,0.990192,0),NumberSequenceKeypoint.new(1,1,0)})},
