					{"Speed", NumberRange.new(13,33)},
					{"Size", NumberSequence.new({NumberSequenceKeypoint.new(0,0,0),NumberSequenceKeypoint.new(0.103491,0.275031,0.0750084),NumberSequenceKeypoint.new(1,0,0)})},
					{"Color", ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.new(0.588235,0.584314,0.596078)),ColorSequenceKeypoint.new(1,Color3.new(0.588235,0.584314,0.596078))})},
					{"Transparency", NumberSequence.new({NumberSequenceKeypoint.new(0,0,0),NumberSequenceKeypoint.new(1,0,0)})},
					{"Rotation", NumberRange.new(0,360)},
